const { registerBlockVariation } = wp.blocks;
const { __ } = wp.i18n;

registerBlockVariation(
    'core/cover', // Original block name
	{
		name: 'fadie',
		title: __('Fadie', 'flair'),
		description: __('A fullscreen segment with blurring background on scroll.', 'flair'),
		isDefault: false,
		category: 'flair',
		attributes: {
			className: 'flair-fadie',
			minHeight:100,
			minHeightUnit: "vh"
		},
		innerBlocks: [
			['core/group', {
				"style":{ "dimensions":{"minHeight":"150vh"} }, "layout":{"type":"flex","orientation":"vertical","verticalAlignment":"center"}
			}, [
					['core/paragraph', { "align":"center","placeholder":"Write title…" }]
				]
			]
		],
		scope: ['inserter'],
		icon: {
			src: (
			<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
				<path fill="currentColor" d="M21,2H3c-.55,0-1,.45-1,1v18c0,.55.45,1,1,1h18c.55,0,1-.45,1-1V3c0-.55-.45-1-1-1Z"/>
				<path fill="#fff" d="M3.5,3.5v11l1.5-.35v-5.15c1.45,0,2.75,2.78,3.02,4.44l.18-.04c.29-1.13,1.2-3.47,3.8-3.47,2.08,0,3.07.91,3.56,1.73l.59-.14c.39-2.35,1.52-5.53,2.86-5.53v4.85l1.5-.35V3.5H3.5ZM8.8,8.76c-.96,0-1.74-.78-1.74-1.74s.78-1.74,1.74-1.74,1.74.78,1.74,1.74-.78,1.74-1.74,1.74Z"/>
			</svg>
			)
		},
		isActive: ( blockAttributes ) => {
			// check that the value exists; otherwise default covers break
			if( ! blockAttributes || ! blockAttributes.className ) { return }
			return blockAttributes.className.includes( 'flair-fadie' );
		}
	}
);
